import {floorRecord,reportStale} from './planning-data.js';
export function planningOverlay(project,floor){const r=floorRecord(project,floor.id);if(!r.assessment||reportStale(r.assessment,floor,r.context))return '';const points=new Map();for(const x of r.assessment.findings){if(!x.point)continue;const key=x.roomId,old=points.get(key);if(!old||['Conflict','Unknown','Aligned','Not applicable'].indexOf(x.status)<['Conflict','Unknown','Aligned','Not applicable'].indexOf(old.status))points.set(key,x);}return `<g pointer-events="none">${[...points.values()].map(x=>`<g><circle cx="${x.point.x}" cy="${x.point.z}" r=".18" fill="${{Aligned:'#69a883',Conflict:'#df8f65',Unknown:'#a99bb9','Not applicable':'#8e939c'}[x.status]}" stroke="white" stroke-width=".035"/><text x="${x.point.x}" y="${x.point.z+.06}" text-anchor="middle" font-size=".2" fill="#17151b">${{Aligned:'✓',Conflict:'!',Unknown:'?','Not applicable':'–'}[x.status]}</text></g>`).join('')}</g>`;}
